import { useState } from 'react';
import axios from 'axios';

const RegistrationForm = () => {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleSubmit = async (event) => {
    event.preventDefault();

    try {
      const response = await axios.post(`${process.env.REACT_APP_API_URL}/api/register`, {
        name, email, password
      });

      if (response.data.success === true) {
        alert("Регистрация прошла успешно!");
      } else {
        alert(response.data.message || "Возникла проблема при регистрации.");
      }
    } catch (error) {
      if (error.response && error.response.data) {
        alert(error.response.data.message || "Ошибка регистрации");
      } else {
        alert("Что-то пошло не так при попытке зарегистрироваться. Проверьте подключение к Интернету.");
      }
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <input placeholder='Имя' value={name} onChange={(e) => setName(e.target.value)} /><br/>
      <input placeholder='Email' value={email} onChange={(e) => setEmail(e.target.value)} /><br/>
      <input type='password' placeholder='Пароль' value={password} onChange={(e) => setPassword(e.target.value)} /><br/>
      <button type='submit'>Зарегистрироваться</button>
    </form>
  );
};

export default RegistrationForm;
